def scout_output() -> str:
    """What the scout command prints. It holds the practice logins: keep it in memory, never print or store it."""
    command = [find_atira(), *SCOUT]
    try:
        done = subprocess.run(command, stdin=subprocess.DEVNULL, capture_output=True, timeout=120)
    except (OSError, subprocess.TimeoutExpired) as error:
        raise SystemExit(f"local_run: cannot run `atira {' '.join(SCOUT)}`: {error}")
    if done.returncode != 0:  # its stdout stays unseen; stderr is the CLI's own explanation
        reason = done.stderr.decode("utf-8", errors="replace").strip()
        raise SystemExit(f"local_run: `atira {' '.join(SCOUT)}` failed with exit code {done.returncode}\n{reason}")
    return done.stdout.decode("utf-8-sig", errors="replace")

